def investigate(context, acquire):
    receipts = acquire("history")
    if not receipts:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, instrument, channel_mode):
        # state: dict key -> value for committed rows
        state = {}
        # per-connection transaction buffers: None means no open txn
        txn = {"main": None, "other": None}
        # total_changes per connection
        total = {"main": 0, "other": 0}
        # last changes() per connection
        last = {"main": 0, "other": 0}
        # log rows inserted by trigger
        log_count = 0

        def apply_write(conn, key, value, is_update, is_delete):
            nonlocal log_count
            # determine effect on committed state
            if is_delete:
                if key in state:
                    del state[key]
                    changed = 1
                else:
                    changed = 0
            elif is_update:
                if key in state:
                    state[key] = value
                    changed = 1
                else:
                    changed = 0
            else:
                # put
                if key in state:
                    if put_mode == "ignore":
                        changed = 0
                    elif put_mode == "replace":
                        state[key] = value
                        changed = 1
                    else:  # upsert
                        state[key] = value
                        changed = 1
                else:
                    state[key] = value
                    changed = 1
            if changed:
                total[conn] += changed
                last[conn] = changed
                if instrument and not is_delete:
                    # AFTER INSERT trigger fires on insert (put) and on replace/upsert insert
                    # For replace, it's a delete+insert, trigger fires on insert
                    # For upsert, trigger fires on insert
                    log_count += 1
            else:
                last[conn] = 0
            return changed

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                txn[conn] = {}
            elif op == "commit":
                if txn[conn] is not None:
                    # apply buffered writes to committed state
                    for (k, v, is_upd, is_del) in txn[conn].get("writes", []):
                        apply_write(conn, k, v, is_upd, is_del)
                    txn[conn] = None
            elif op == "rollback":
                txn[conn] = None
            elif op in ("put", "update", "delete"):
                key = act.get("key")
                value = act.get("value", 0)
                is_upd = (op == "update")
                is_del = (op == "delete")
                if txn[conn] is not None:
                    txn[conn].setdefault("writes", []).append((key, value, is_upd, is_del))
                else:
                    apply_write(conn, key, value, is_upd, is_del)

        if channel_mode == "changes":
            return last["main"]
        elif channel_mode == "total_main":
            return total["main"]
        else:
            return total["main"] + total["other"]

    # Enumerate family members
    put_modes = ["ignore", "replace", "upsert"]
    instruments = [False, True]
    channel_modes = ["changes", "total_main", "total_both"]

    candidates = []
    for pm in put_modes:
        for inst in instruments:
            for cm in channel_modes:
                candidates.append((pm, inst, cm))

    # Filter candidates by calibration receipts
    consistent = []
    for (pm, inst, cm) in candidates:
        ok = True
        for r in receipts:
            acts = r.get("actions", [])
            obs = r.get("observed", {})
            ch = simulate(acts, pm, inst, cm)
            if ch != obs.get("channel"):
                ok = False
                break
            # committed state check
            st = {}
            txn = {"main": None, "other": None}
            for act in acts:
                op = act.get("op")
                conn = act.get("connection", "main")
                if op == "begin":
                    txn[conn] = []
                elif op == "commit":
                    if txn[conn] is not None:
                        for (k, v, iu, idl) in txn[conn]:
                            if idl:
                                if k in st: del st[k]
                            elif iu:
                                if k in st: st[k] = v
                            else:
                                if k in st:
                                    if pm == "ignore": pass
                                    else: st[k] = v
                                else:
                                    st[k] = v
                        txn[conn] = None
                elif op == "rollback":
                    txn[conn] = None
                elif op in ("put", "update", "delete"):
                    k = act.get("key")
                    v = act.get("value", 0)
                    iu = (op == "update")
                    idl = (op == "delete")
                    if txn[conn] is not None:
                        txn[conn].append((k, v, iu, idl))
                    else:
                        if idl:
                            if k in st: del st[k]
                        elif iu:
                            if k in st: st[k] = v
                        else:
                            if k in st:
                                if pm == "ignore": pass
                                else: st[k] = v
                            else:
                                st[k] = v
            if len(st) != obs.get("committed_count"):
                ok = False
                break
            if sum(st.values()) != obs.get("committed_sum"):
                ok = False
                break
        if ok:
            consistent.append((pm, inst, cm))

    if not consistent:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])

    # Compute goal for each consistent candidate
    results = []
    for (pm, inst, cm) in consistent:
        if goal == "channel":
            results.append(simulate(actions, pm, inst, cm))
        else:
            # committed state
            st = {}
            txn = {"main": None, "other": None}
            for act in actions:
                op = act.get("op")
                conn = act.get("connection", "main")
                if op == "begin":
                    txn[conn] = []
                elif op == "commit":
                    if txn[conn] is not None:
                        for (k, v, iu, idl) in txn[conn]:
                            if idl:
                                if k in st: del st[k]
                            elif iu:
                                if k in st: st[k] = v
                            else:
                                if k in st:
                                    if pm == "ignore": pass
                                    else: st[k] = v
                                else:
                                    st[k] = v
                        txn[conn] = None
                elif op == "rollback":
                    txn[conn] = None
                elif op in ("put", "update", "delete"):
                    k = act.get("key")
                    v = act.get("value", 0)
                    iu = (op == "update")
                    idl = (op == "delete")
                    if txn[conn] is not None:
                        txn[conn].append((k, v, iu, idl))
                    else:
                        if idl:
                            if k in st: del st[k]
                        elif iu:
                            if k in st: st[k] = v
                        else:
                            if k in st:
                                if pm == "ignore": pass
                                else: st[k] = v
                            else:
                                st[k] = v
            if goal == "committed_count":
                results.append(len(st))
            else:
                results.append(sum(st.values()))

    if len(set(results)) == 1:
        return {"value": results[0], "unresolved": False}
    return {"value": None, "unresolved": True}
